+        ["notifications"] = ("Notifications", "bi-bell"),
+        ["security"] = ("Security", "bi-shield-lock"),
+        ["appearance"] = ("Appearance", "bi-palette"),
+    };
+
+    private string _activeSection = "profile";
+    private bool _loading = true;
+
+    // Toast state
+    private bool _toastVisible;
+    private string _toastMessage = "";
+    private CancellationTokenSource? _toastCts;
+
+    // Profile state
+    private string _profileName = "";
+    private string _profileEmail = "";
+    private string _profileBio = "";
+    private string _profileAvatarUrl = "";
+    private UserProfile? _savedProfile;
+
+    // Notification state
+    private bool _emailNotifications;
+    private bool _pushNotifications;
+    private bool _weeklyDigest;
+    private List<(string Channel, bool Muted)> _channels = [];
+
+    // Security state
+    private SecuritySettings? _securitySettings;
+    private bool _twoFactorEnabled;
+    private bool _changePasswordExpanded;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private string? _passwordError;
+    private bool _showRevokeConfirm;
+    private ActiveSession? _sessionToRevoke;
+    private bool _revoking;
+    private bool _changingPassword;
+
+    // Appearance state
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+    private readonly string[] _themes = ["Light", "Dark", "System"];
+    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
+    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];
+
+    // Saving flags
+    private bool _savingProfile;
+    private bool _savingNotifications;
+    private bool _savingAppearance;
+
+    protected override async Task OnInitializedAsync()
+    {
+        var profileTask = SettingsService.GetProfileAsync();
+        var notifsTask = SettingsService.GetNotificationPrefsAsync();
+        var securityTask = SettingsService.GetSecuritySettingsAsync();
+        var appearanceTask = SettingsService.GetAppearanceAsync();
+
+        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);
+
+        var profile = profileTask.Result;
+        _savedProfile = profile;
+        _profileName = profile.DisplayName;
+        _profileEmail = profile.Email;
+        _profileBio = profile.Bio;
+        _profileAvatarUrl = profile.AvatarUrl;
+
+        var notifs = notifsTask.Result;
+        _emailNotifications = notifs.EmailNotifications;
+        _pushNotifications = notifs.PushNotifications;
+        _weeklyDigest = notifs.WeeklyDigest;
+        _channels = notifs.MutedChannels.Select(c => (c, true)).ToList();
+
+        _securitySettings = securityTask.Result;
+        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
+
+        var appearance = appearanceTask.Result;
+        _theme = appearance.Theme;
+        _fontSize = appearance.FontSize;
+        _language = appearance.Language;
+        _compactMode = appearance.CompactMode;
+
+        _loading = false;
+    }
+
+    // --- Toast helper ---
+
+    private async Task ShowToast(string message)
+    {
+        _toastCts?.Cancel();
+        _toastCts = new CancellationTokenSource();
+        var token = _toastCts.Token;
+
+        _toastMessage = message;
+        _toastVisible = true;
+        StateHasChanged();
+
+        try
+        {
+            await Task.Delay(3000, token);
+            _toastVisible = false;
+            StateHasChanged();
+        }
+        catch (TaskCanceledException) { }
+    }
+
+    // --- Profile ---
+
+    private RenderFragment RenderProfile() => __builder =>
+    {
+        <h4 class="mb-4">Profile Settings</h4>
+
+        <div class="row">
+            <div class="col-md-8">
+                <div class="mb-3">
+                    <label class="form-label fw-semibold">Display Name</label>
+                    <input type="text" class="form-control" @bind="_profileName" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label fw-semibold">Email</label>
+                    <input type="email" class="form-control" @bind="_profileEmail" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label fw-semibold">Bio</label>
+                    <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
+                </div>
+            </div>
+            <div class="col-md-4 text-center">
+                <label class="form-label fw-semibold d-block">Avatar Preview</label>
+                <div class="mb-2">
+                    @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
+                    {
+                        <img src="@_profileAvatarUrl" alt="Avatar" class="rounded-circle border"
+                             style="width: 120px; height: 120px; object-fit: cover;" />
+                    }
+                    else
+                    {
+                        <div class="rounded-circle bg-secondary d-inline-flex align-items-center justify-content-center"
+                             style="width: 120px; height: 120px;">
+                            <span class="text-white fs-1">@(_profileName.Length > 0 ? _profileName[0] : '?')</span>
+                        </div>
+                    }
+                </div>
+                <small class="text-muted text-break">@_profileAvatarUrl</small>
+            </div>
+        </div>
+
+        <hr />
+
+        <div class="d-flex gap-2">
+            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_savingProfile">
+                @if (_savingProfile)
+                {
+                    <span class="spinner-border spinner-border-sm me-1"></span>
+                }
+                Save Changes
+            </button>
+            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
+        </div>
+    };
+
+    private async Task SaveProfile()
+    {
+        _savingProfile = true;
+        var profile = new UserProfile(_profileName, _profileEmail, _profileAvatarUrl, _profileBio);
+        await SettingsService.SaveProfileAsync(profile);
+        _savedProfile = profile;
+        _savingProfile = false;
+        await ShowToast("Profile saved successfully!");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (_savedProfile is not null)
+        {
+            _profileName = _savedProfile.DisplayName;
+            _profileEmail = _savedProfile.Email;
+            _profileBio = _savedProfile.Bio;
+            _profileAvatarUrl = _savedProfile.AvatarUrl;
+        }
+    }
+
+    // --- Notifications ---
+
+    private RenderFragment RenderNotifications() => __builder =>
+    {
+        <h4 class="mb-4">Notification Preferences</h4>
+
+        <div class="mb-4">
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
+                <label class="form-check-label" for="emailNotif">
+                    <strong>Email Notifications</strong>
+                    <br /><small class="text-muted">Receive notifications via email</small>
+                </label>
+            </div>
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
+                <label class="form-check-label" for="pushNotif">
+                    <strong>Push Notifications</strong>
+                    <br /><small class="text-muted">Receive browser push notifications</small>
+                </label>
+            </div>
+            <div class="form-check form-switch mb-3">
+                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
+                <label class="form-check-label" for="weeklyDigest">
+                    <strong>Weekly Digest</strong>
+                    <br /><small class="text-muted">Receive a weekly summary email</small>
+                </label>
+            </div>
+        </div>
+
+        <h5 class="mb-3">Muted Channels</h5>
+        <div class="mb-4">
+            @for (var i = 0; i < _channels.Count; i++)
+            {
+                var index = i;
+                var channel = _channels[index];
+                <div class="form-check mb-2">
+                    <input class="form-check-input" type="checkbox" id="@($"ch-{index}")"
+                           checked="@channel.Muted"
+                           @onchange="e => _channels[index] = (channel.Channel, (bool)(e.Value ?? false))" />
+                    <label class="form-check-label text-capitalize" for="@($"ch-{index}")">
+                        @channel.Channel
+                    </label>
+                </div>
+            }
+        </div>
+
+        <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_savingNotifications">
+            @if (_savingNotifications)
+            {
+                <span class="spinner-border spinner-border-sm me-1"></span>
+            }
+            Save Preferences
+        </button>
+    };
+
+    private async Task SaveNotifications()
+    {
+        _savingNotifications = true;
+        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Channel).ToList();
+        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        _savingNotifications = false;
+        await ShowToast("Notification preferences saved!");
+    }
+
+    // --- Security ---
+
+    private RenderFragment RenderSecurity() => __builder =>
+    {
+        <h4 class="mb-4">Security Settings</h4>
+
+        <!-- Change Password expandable panel -->
+        <div class="card mb-4">
+            <div class="card-header d-flex justify-content-between align-items-center"
+                 style="cursor: pointer;" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
+                <strong>Change Password</strong>
+                <i class="bi @(_changePasswordExpanded ? "bi-chevron-up" : "bi-chevron-down")"></i>
+            </div>
+            @if (_changePasswordExpanded)
+            {
+                <div class="card-body">
+                    <div class="row">
+                        <div class="col-md-6">
+                            <div class="mb-3">
+                                <label class="form-label">Current Password</label>
+                                <input type="password" class="form-control" @bind="_currentPassword" />
+                            </div>
+                            <div class="mb-3">
+                                <label class="form-label">New Password</label>
+                                <input type="password" class="form-control" @bind="_newPassword" />
+                            </div>
+                            <div class="mb-3">
+                                <label class="form-label">Confirm New Password</label>
+                                <input type="password" class="form-control" @bind="_confirmPassword" />
+                            </div>
+                            @if (_passwordError is not null)
+                            {
+                                <div class="alert alert-danger py-2">@_passwordError</div>
+                            }
+                            <button class="btn btn-warning" @onclick="ChangePassword" disabled="@_changingPassword">
+                                @if (_changingPassword)
+                                {
+                                    <span class="spinner-border spinner-border-sm me-1"></span>
+                                }
+                                Update Password
+                            </button>
+                        </div>
+                        <div class="col-md-6">
+                            @if (_securitySettings?.LastPasswordChange is not null)
+                            {
+                                <div class="alert alert-info mt-md-4">
+                                    Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
+                                </div>
+                            }
+                        </div>
+                    </div>
+                </div>
+            }
+        </div>
+
+        <!-- Two-factor authentication -->
+        <div class="card mb-4">
+            <div class="card-body d-flex justify-content-between align-items-center">
+                <div>
+                    <strong>Two-Factor Authentication</strong>
+                    <br />
+                    <span class="badge @(_twoFactorEnabled ? "text-bg-success" : "text-bg-secondary") mt-1">
+                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
+                    </span>
+                </div>
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" style="transform: scale(1.3);"
+                           @bind="_twoFactorEnabled" />
+                </div>
+            </div>
+        </div>
+
+        <!-- Active Sessions -->
+        <h5 class="mb-3">Active Sessions</h5>
+        @if (_securitySettings?.Sessions is { Count: > 0 })
+        {
+            <div class="table-responsive">
+                <table class="table table-hover align-middle">
+                    <thead class="table-light">
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th></th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @foreach (var session in _securitySettings.Sessions)
+                        {
+                            var isCurrentSession = session == _securitySettings.Sessions.First();
+                            <tr>
+                                <td>
+                                    @session.Device
+                                    @if (isCurrentSession)
+                                    {
+                                        <span class="badge text-bg-primary ms-2">Current</span>
+                                    }
+                                </td>
+                                <td>@session.Location</td>
+                                <td>@FormatLastActive(session.LastActive)</td>
+                                <td class="text-end">
+                                    @if (!isCurrentSession)
+                                    {
+                                        <button class="btn btn-sm btn-outline-danger"
+                                                @onclick="() => PromptRevokeSession(session)">
+                                            Revoke
+                                        </button>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    </tbody>
+                </table>
+            </div>
+        }
+        else
+        {
+            <p class="text-muted">No active sessions.</p>
+        }
+    };
+
+    private async Task ChangePassword()
+    {
+        _passwordError = null;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword))
+        {
+            _passwordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
+        {
+            _passwordError = "New password must be at least 8 characters.";
+            return;
+        }
+        if (_newPassword != _confirmPassword)
+        {
+            _passwordError = "Passwords do not match.";
+            return;
+        }
+
+        _changingPassword = true;
+        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        _currentPassword = "";
+        _newPassword = "";
+        _confirmPassword = "";
+        _changingPassword = false;
+        _changePasswordExpanded = false;
+        await ShowToast("Password updated successfully!");
+    }
+
+    private void PromptRevokeSession(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+        _showRevokeConfirm = true;
+    }
+
+    private async Task ConfirmRevokeSession()
+    {
+        if (_sessionToRevoke is null) return;
+
+        _revoking = true;
+        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        _revoking = false;
+        _showRevokeConfirm = false;
+        _sessionToRevoke = null;
+        await ShowToast("Session revoked successfully!");
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+
